describe('File Upload Retry Functionality', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000/upload');
    cy.get('[data-testid="file-input"]').as('fileInput');
    cy.get('[data-testid="upload-button"]').as('uploadButton');
    cy.get('[data-testid="retry-button"]').as('retryButton');
    cy.get('[data-testid="upload-status"]').as('uploadStatus');
  });

  it('should retry a failed upload without re-selecting the file', () => {
    const fileName = 'test-file.pdf';

    cy.fixture(fileName).then(fileContent => {
      cy.get('@fileInput').selectFile({
        contents: Cypress.Buffer.from(fileContent),
        fileName: fileName,
        mimeType: 'application/pdf'
      });
    });

    cy.get('@uploadButton').click();

    cy.get('@uploadStatus').should('contain', 'Upload failed');
    cy.get('@retryButton').should('be.visible');

    cy.get('@retryButton').click();

    cy.get('@uploadStatus').should('contain', 'Uploading');
    cy.get('@uploadStatus').should('contain', 'Upload successful');
    cy.get('@retryButton').should('not.be.visible');
  });

  it('should maintain file selection after multiple failed retry attempts', () => {
    const fileName = 'large-file.zip';

    cy.fixture(fileName).then(fileContent => {
      cy.get('@fileInput').selectFile({
        contents: Cypress.Buffer.from(fileContent),
        fileName: fileName,
        mimeType: 'application/zip'
      });
    });

    cy.get('@uploadButton').click();
    cy.get('@uploadStatus').should('contain', 'Upload failed');

    cy.get('@retryButton').click();
    cy.get('@uploadStatus').should('contain', 'Upload failed');

    cy.get('@retryButton').should('be.visible');
    cy.get('@retryButton').click();

    cy.get('@uploadStatus').should('contain', 'Upload successful');
    cy.get('[data-testid="file-name"]').should('contain', fileName);
  });

  it('should display retry button only on failed uploads', () => {
    const fileName = 'valid-file.txt';

    cy.fixture(fileName).then(fileContent => {
      cy.get('@fileInput').selectFile({
        contents: Cypress.Buffer.from(fileContent),
        fileName: fileName,
        mimeType: 'text/plain'
      });
    });

    cy.get('@uploadButton').click();

    cy.get('@uploadStatus').should('contain', 'Upload successful');
    cy.get('@retryButton').should('not.exist');
  });

  it('should clear retry state when selecting a new file', () => {
    const firstFile = 'file1.pdf';
    const secondFile = 'file2.pdf';

    cy.fixture(firstFile).then(fileContent => {
      cy.get('@fileInput').selectFile({
        contents: Cypress.Buffer.from(fileContent),
        fileName: firstFile,
        mimeType: 'application/pdf'
      });
    });

    cy.get('@uploadButton').click();
    cy.get('@uploadStatus').should('contain', 'Upload failed');
    cy.get('@retryButton').should('be.visible');

    cy.fixture(secondFile).then(fileContent => {
      cy.get('@fileInput').selectFile({
        contents: Cypress.Buffer.from(fileContent),
        fileName: secondFile,
        mimeType: 'application/pdf'
      });
    });

    cy.get('@retryButton').should('not.be.visible');
    cy.get('[data-testid="file-name"]').should('contain', secondFile);
  });
});
